messages.content:
Önceki kesin metin yamalarında parantez sınırı belirsizliği sözdizimini bozdu; uygulama eşleştirmesi de başarısız. ArtıkikifonksiyonunTAMAMINI üret. JSON{"doLoad":"tam function doLoad() {...}","onFile":"tam function onFile(e) {...}"}. Aynıg,sel,last,uiAcc,playing,speed ve yardımcıları kullan. g=s valid deserialize sonrası koşuldanÖNCE onPointerCancel({pointerId:drag?.pointerId}); speed=1;$('speedSelect').value='1';document.querySelector('.stage').classList.add('game-active');sel=null;last=0;uiAcc=0. g.overyseplayingfalse,endOverlayhiddenfalse,showEnd. Aksi g.pausedtrue,playingtrue,startoverlayhidden,endoverlayhidden,setErr. onFile size100KB,rdonerror,invalidverimevcutoyunudeğiştirme. globalstage değişkenYOK. Sözdizimi tam validJS. JSONyalnız. Eski bozukfonksiyonlar:
function doLoad() {
  try {
    const raw = localStorage.getItem(SAVE_KEY); if (!raw) { setErr('Kayıt yok.'); return; }
    const s = deserialize(raw);
    if (!s || !s.planes || !s.runways) throw new Error('geçersiz veri');
    g = s; sel = null; last = 0; uiAcc = 0;
    if (g.over) { onPointerCancel({pointerId:drag?.pointerId}); speed=1; $('speedSelect').value='1'; stage.classList.add('game-active'); } {
      g.paused = true;
      playing = false;
      $('startOverlay').hidden = true;
      $('endOverlay').hidden = false;
      showEnd();
    } else {
      g.paused = true;
      playing = true;
      $('startOverlay').hidden = true;
      $('endOverlay').hidden = true;
      setErr('Yüklendi (duraklatıldı).');
    }
    updateUI();
  } catch (e) { setErr('Yükleme hatası: ' + e.message); }
}

function onFile(e) {
  const f = e.target.files[0]; e.target.value = '';
  if (!f) return;
  if (f.size > 100 * 1024) { setErr('Dosya çok büyük (max 100KB).'); return; }
  const rd = new FileReader();
  rd.onload = () => {
    try {
      const s = deserialize(String(rd.result));
      if (!s || !s.planes || !s.runways) throw new Error('geçersiz veri');
      g = s; sel = null; last = 0; uiAcc = 0;
      if (g.over) { onPointerCancel({pointerId:drag?.pointerId}); speed=1; $('speedSelect').value='1'; stage.classList.add('game-active'); } {
        g.paused = true;
        playing = false;
        $('startOverlay').hidden = true;
        $('endOverlay').hidden = false;
        showEnd();
      } else {
        g.paused = true;
        playing = true;
        $('startOverlay').hidden = true;
        $('endOverlay').hidden = true;
        setErr('İçe aktarıldı (duraklatıldı).');
      }
      updateUI();
    } catch (ex) { setErr('İçe aktarma hatası: ' + ex.message); }
  };
  rd.onerror = () => setErr('Dosya okunamadı.');
  rd.readAsText(f);
}
